-- title: Data provenance - how each establishment kind's waste figures were captured
-- concepts: column added by ALTER TABLE (measurement_source), conditional aggregates, percentage with NULLIF
-- purpose: Not all numbers are equally trustworthy. This reports, per kind, what share of waste kilograms was typed in by a person (MANUAL), imported from a field-log document (ETL_IMPORT) or generated by the system (SYSTEM). It replaces the PDF's forecast-accuracy query #21, which needs the forecasting tables that belong to the optional Part 4.
-- mode: select
-- reading: manual_pct + etl_import_pct + system_pct = 100 for each kind. A high etl_import_pct means that kind's figures come mostly from field-log documents.
SELECT ec.kind,
       COUNT(*)                                                                     AS events,
       ROUND(SUM(w.quantity_kg))                                                    AS total_kg,
       ROUND(100.0 * SUM(w.quantity_kg) FILTER (WHERE w.measurement_source = 'MANUAL')     / SUM(w.quantity_kg), 1) AS manual_pct,
       ROUND(100.0 * SUM(w.quantity_kg) FILTER (WHERE w.measurement_source = 'ETL_IMPORT') / SUM(w.quantity_kg), 1) AS etl_import_pct,
       ROUND(100.0 * SUM(w.quantity_kg) FILTER (WHERE w.measurement_source = 'SYSTEM')     / SUM(w.quantity_kg), 1) AS system_pct
  FROM waste_event w
  JOIN waste_reason wr           ON wr.reason_id = w.reason_id AND wr.reason_code <> 'REDISTRIBUTED'
  JOIN establishment e           ON e.establishment_id = w.establishment_id
  JOIN establishment_category ec ON ec.category_id = e.category_id
 GROUP BY ec.kind
 ORDER BY total_kg DESC;
